// Resilient Raft Quorum Calculator & Leader Lease Enforcement
export class ConsensusClusterGuard {
  constructor(private totalNodes: number) {
    if (totalNodes % 2 === 0) {
      console.warn("DANGER: Even node count increases split-brain risk without arbiter!");
    }
  }

  getQuorumSize(): number {
    // Strictly requires more than 50% of the cluster
    return Math.floor(this.totalNodes / 2) + 1;
  }

  canElectLeader(voteCount: number): boolean {
    return voteCount >= this.getQuorumSize();
  }

  // Leader Lease: Leader must successfully heartbeat majority within lease window
  verifyLeaderLease(ackedHeartbeats: number, lastLeaseTime: number, leaseDurationMs = 5000): boolean {
    const now = Date.now();
    const hasQuorum = ackedHeartbeats >= this.getQuorumSize();
    const isLeaseFresh = (now - lastLeaseTime) < leaseDurationMs;

    if (!hasQuorum || !isLeaseFresh) {
      // Step down immediately to prevent dual-leader split-brain writes!
      throw new Error("Leader stepped down: Lost majority quorum lease!");
    }
    return true;
  }
}

// Production Solution: Single-Flight Mutex + TTL Jitter
import Redis from "ioredis";
const redis = new Redis();

export async function getSafeCachedProduct<T>(
  productId: string,
  baseTtlSec: number,
  dbLoader: () => Promise<T>
): Promise<T> {
  const cacheKey = `prod:${productId}`;
  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached);

  const lockKey = `lock:${cacheKey}`;
  // 1. Single-Flight Mutex: Acquire 5s lock
  const acquired = await redis.set(lockKey, "1", "NX", "EX", 5);

  if (acquired) {
    try {
      const freshData = await dbLoader();
      // 2. TTL Jitter: Add random +/- 20% variance to prevent synchronized avalanche!
      const jitterDelta = (Math.random() * 0.4 - 0.2) * baseTtlSec;
      const safeTtl = Math.floor(baseTtlSec + jitterDelta);

      await redis.setex(cacheKey, safeTtl, JSON.stringify(freshData));
      return freshData;
    } finally {
      await redis.del(lockKey);
    }
  } else {
    // Other threads sleep and retry reading warm cache
    await new Promise((r) => setTimeout(r, 60));
    return getSafeCachedProduct(productId, baseTtlSec, dbLoader);
  }
}

