// NTP Drift Monitor Daemon & Safe LWW Guard
import { exec } from "child_process";

export function checkNtpClockOffset(maxDriftMs = 50): Promise<number> {
  return new Promise((resolve, reject) => {
    // Query local NTP peer offset via ntpq
    exec("ntpq -pn | awk 'NR>2 {print $9}' | head -n 1", (err, stdout) => {
      if (err) return reject(err);
      const offsetMs = Math.abs(parseFloat(stdout.trim()));

      if (isNaN(offsetMs)) {
        return reject(new Error("Unable to parse NTP offset"));
      }

      if (offsetMs > maxDriftMs) {
        // CRITICAL ALERT: Clock drift exceeds safety threshold!
        console.error(`CRITICAL: NTP Clock drift is ${offsetMs}ms (Threshold: ${maxDriftMs}ms)!`);
        // Remove node from Cassandra ring or mark unhealthy to prevent silent data corruption!
      }
      resolve(offsetMs);
    });
  });
}

// Cross-Region Read-Your-Own-Writes Enforcement via Session Pinning
export class CrossRegionConsistencyManager {
  private userRecentWrites = new Map<string, number>(); // userId -> writeTimestamp

  recordWrite(userId: string) {
    this.userRecentWrites.set(userId, Date.now());
  }

  shouldRouteToPrimary(userId: string, replicationLagToleranceMs = 5000): boolean {
    const lastWrite = this.userRecentWrites.get(userId);
    if (!lastWrite) return false;

    const timeSinceLastWrite = Date.now() - lastWrite;
    // If user modified data within the replication lag window, FORCE read to Primary!
    return timeSinceLastWrite < replicationLagToleranceMs;
  }
}

