// Two-Phase Salting Algorithm to Eliminate Hot Partition Key Skew
import crypto from "crypto";

export class PartitionSaltKeyGenerator {
  constructor(private saltBuckets = 8) {}

  generateSaltedKey(originalKey: string): string {
    // If the key is a known heavy hotspot, append a random salt suffix
    if (originalKey === "smart_meter") {
      const salt = Math.floor(Math.random() * this.saltBuckets);
      return `${originalKey}#salt_${salt}`; // Disperses across 8 different Kafka partitions!
    }
    return originalKey;
  }
}

