// Resilient Circuit Breaker with Exponential Backoff and Full Jitter
export async function executeResilientCall<T>(
  action: () => Promise<T>,
  fallback: () => Promise<T>,
  maxRetries = 3,
  baseDelayMs = 100,
  capDelayMs = 4000
): Promise<T> {
  let attempt = 0;

  while (true) {
    try {
      return await action();
    } catch (err) {
      if (attempt >= maxRetries) {
        console.warn("Retries exhausted! Executing fallback.");
        return fallback();
      }
      attempt++;

      // Full Jitter calculation: rand(0, min(cap, base * 2^attempt))
      const expCap = Math.min(capDelayMs, baseDelayMs * Math.pow(2, attempt));
      const jitteredSleep = Math.floor(Math.random() * expCap);

      console.log(`Attempt ${attempt} failed. Sleeping ${jitteredSleep}ms (Full Jitter)...`);
      await new Promise(r => setTimeout(r, jitteredSleep));
    }
  }
}

// Resilient Poison Pill Interceptor with Dead Letter Queue Routing
export async function processQueueSafely(
  message: { id: string; rawBody: string; retryCount: number },
  businessLogic: (parsed: any) => Promise<void>,
  dlqPublisher: (msg: any) => Promise<void>
) {
  let parsedPayload: any;

  // 1. Safe JSON parsing guard
  try {
    parsedPayload = JSON.parse(message.rawBody);
  } catch (parseError: any) {
    console.error(`Poison pill detected (JSON corrupt) in ${message.id}! Routing directly to DLQ.`);
    await dlqPublisher({ id: message.id, body: message.rawBody, error: "JSON_PARSE_ERROR" });
    return; // Acknowledge message to remove from active stream!
  }

  // 2. Business logic execution with retry bounds
  try {
    await businessLogic(parsedPayload);
  } catch (execError: any) {
    if (message.retryCount >= 3) {
      console.error(`Message ${message.id} exceeded retry limit. Quarantining to DLQ.`);
      await dlqPublisher({ id: message.id, payload: parsedPayload, error: execError.message });
    } else {
      throw execError; // Trigger transient retry
    }
  }
}

// Trace Header Invariant Verification Middleware
export function traceHeaderEnforcementMiddleware(req: any, res: any, next: any) {
  const traceparent = req.headers["traceparent"];

  if (!traceparent) {
    // If incoming request lacks traceparent, generate a new one and log warning
    const newTraceId = crypto.randomBytes(16).toString("hex");
    const newSpanId = crypto.randomBytes(8).toString("hex");
    req.headers["traceparent"] = `00-${newTraceId}-${newSpanId}-01`;
    console.warn("WARNING: Missing incoming traceparent header! Trace context was dropped upstream.");
  }

  // Ensure outgoing HTTP client libraries automatically forward this header!
  next();
}

// Storage Protection via Monotonic Fencing Tokens
export class LedgerStorageWithFencing {
  private currentMaxToken = 0;

  async writeLedgerEntry(fencingToken: number, entryData: any) {
    // CRITICAL: Reject any write whose fencing token is older than the highest observed token!
    if (fencingToken < this.currentMaxToken) {
      throw new Error(
        `DATA CORRUPTION PREVENTED: Stale write with token ${fencingToken} rejected! Current max token is ${this.currentMaxToken}`
      );
    }

    this.currentMaxToken = fencingToken;
    await executeDatabaseInsert(entryData);
    console.log(`Ledger entry committed safely with fencing token ${fencingToken}`);
  }
}

// Pre-Vote Raft Protocol Extension to Neutralize Asymmetric Partitions
export class ResilientRaftNode {
  // Pre-Vote Phase: Before incrementing term and starting real election,
  // probe cluster to see if a majority can actually hear this node!
  async runPreVotePhase(peers: string[], sendPreVoteRpc: (peer: string) => Promise<boolean>): Promise<boolean> {
    console.log("Starting Pre-Vote phase to verify bidirectional connectivity...");

    const votes = await Promise.all(peers.map(p => sendPreVoteRpc(p)));
    const affirmativeVotes = votes.filter(v => v === true).length + 1; // Count self
    const majority = Math.floor((peers.length + 1) / 2) + 1;

    if (affirmativeVotes >= majority) {
      console.log("Pre-Vote SUCCESS: Node has confirmed bidirectional quorum connectivity!");
      return true;
    } else {
      console.warn("Pre-Vote FAILED: Node is isolated or in asymmetric partition. Aborting election.");
      return false; // Do NOT increment term! Protects cluster from disruptive elections.
    }
  }
}
